INSERT IGNORE INTO page_section (page_key, section_key, area_code, title, body_html, sort_order) VALUES
  ('academic.academiccouncil', 'main', 'academic', 'MoM of Academic Council: text', '<p><strong>Updated Soon&#8230</strong></p>', 10),
  ('academic.admission', 'heading', 'academic', 'UG Admission: heading', '<h3 id="ctl00_ContentPlaceHolder1_h4_heading">Entrance Test</h3>', 10),
  ('academic.admission', 'entrance', 'academic', 'UG Admission: entrance test and first-year qualification', '<p>Admission in Katihar Engineering College (KEC) for four years\r\n                                                        B.Tech.\r\n                                                        course is made through Bihar Combined Entrance Competitive\r\n                                                        Examination (B.C.E.C.E.) conducted by Bihar Combined Entrance\r\n                                                        Competitive Examination Board. The candidates desirous of\r\n                                                        seeking\r\n                                                        Admission in KEC are advised to appear in competitive\r\n                                                        examination of\r\n                                                        B.C.E.C.E. The details for filling up the form for B.C.E.C.E.,\r\n                                                        fee\r\n                                                        structure, quota and other things is available in its prospectus\r\n                                                        as\r\n                                                        well as on the Website:\r\n                                                        <a\r\n                                                            href="http://bceceboard.bihar.gov.in/pdf_Pros/PROS_BC18.pdf">http://bceceboard.bihar.gov.in/pdf_Pros/PROS_BC18.pdf</a>\r\n                                                    <p> <a\r\n                                                            href="http://bceceboard.bihar.gov.in/">http://bceceboard.bihar.gov.in/</a>\r\n                                                    </p>\r\n                                                    </p>\r\n                                                    <p id="ctl00_ContentPlaceHolder1_h4_heading"><strong>Minimum\r\n                                                            Qualification for admission in first year of UG\r\n                                                            programme</strong></p>\r\n                                                    <div id="ctl00_ContentPlaceHolder1_div_1">The minimum academic\r\n                                                        qualification for admission through BCECE entrance examination\r\n                                                        is a\r\n                                                        pass in the final examination of the Intermediate, 10+2 system\r\n                                                        or\r\n                                                        its equivalent. Those appearing in the Intermediate final or\r\n                                                        equivalent examination may also appear in the entrance\r\n                                                        examination\r\n                                                        for consideration of provisional admission. All provisional\r\n                                                        admissions will stand cancelled, if proof of having passed the\r\n                                                        qualifying examination (Intermediate or equivalent) is not\r\n                                                        submitted\r\n                                                        to the institute at the time of counselling. If an applicant is\r\n                                                        found ineligible at a later date even after admission to the\r\n                                                        KEC,\r\n                                                        his/her admission will be cancelled.\r\n                                                        All admissions will be subject to verification of facts from the\r\n                                                        original certificates/documents of the candidates. The decision\r\n                                                        of\r\n                                                        the B.C.E.C.E. Board regarding eligibility of any applicant\r\n                                                        shall be\r\n                                                        final.\r\n\r\n                                                    </div>\r\n                                                    <p id="ctl00_ContentPlaceHolder1_h4_heading"><strong>Minimum\r\n                                                            Qualification for the direct admission in second year of UG\r\n                                                            programme</strong></p>', 20),
  ('academic.admission', 'lateral', 'academic', 'UG Admission: direct admission in second year', '(A) Passed Diploma\r\n                                                        examination\r\n                                                        with at least 45% marks (40% in case of candidates belonging to\r\n                                                        reserved category) in appropriate branch of Engineering and\r\n                                                        Technology.\r\n                                                        <p>(B) Passed B.Sc. Degree from a recognized University as\r\n                                                            defined\r\n                                                            by UGC, with at least 45% marks (40% in case of candidates\r\n                                                            belonging to reserved category) and passed 10+2 examination\r\n                                                            with\r\n                                                            Mathematics as a subject.\r\n                                                        <p>(C) Provided that the students belonging to B.Sc. Stream,\r\n                                                            shall\r\n                                                            clear the subjects Engineering Graphics / Engineering\r\n                                                            Drawing\r\n                                                            and Engineering Mechanics of the First year Engineering\r\n                                                            Programme along with the Second year subjects.\r\n                                                        <p>(D) Provided that the students belonging to B.Sc. Stream\r\n                                                            shall be\r\n                                                            considered only after filling the supernumerary seats in\r\n                                                            this\r\n                                                            category with students belonging to the Diploma stream', 30),
  ('academic.admission', 'qualifying', 'academic', 'UG Admission: qualifying examinations', '<p><strong>The list of qualifying examinations For\r\n                                                                    Engineering\r\n                                                                    Stream</strong></p>\r\n                                                            <ul>\r\n                                                                <li>Intermediate Examination, Bihar Intermediate\r\n                                                                    Education\r\n                                                                    Council\r\n                                                                </li>\r\n                                                                <li>The 10+2, Central Board of Secondary Education, New\r\n                                                                    Delhi\r\n                                                                </li>\r\n                                                                <li>The 10+2, Council for Indian School Certificate\r\n                                                                    Examination, New Delhi.\r\n                                                                </li>\r\n                                                                <li>The +2 level examination in the 10 +2 pattern of\r\n                                                                    examination of any recognized Central Board of\r\n                                                                    Secondary\r\n                                                                    Examination and Council for Indian School\r\n                                                                    Certificate\r\n                                                                    Examination, New Delhi.\r\n                                                                </li>\r\n                                                                <li>3 or 4 year diploma recognized by AICTE or a state\r\n                                                                    board\r\n                                                                    of technical education. with Physics, Chemistry\r\n                                                                    &amp;\r\n                                                                    Mathematics as combination.\r\n                                                                </li>\r\n                                                            </ul>\r\n\r\n                                                            <div data-animation="bounceInUp" data-animation-delay="0s">\r\n                                                                <div id="ctl00_ContentPlaceHolder1_div_2">\r\n                                                                    <strong>Residential</strong>\r\n                                                                </div>\r\n                                                            </div>', 40),
  ('academic.admission', 'residential', 'academic', 'UG Admission: residential rules', '<p class="text-lg font-medium">Only those\r\n                                                                            candidates\r\n                                                                            can get admission who are citizens of India\r\n                                                                            and:\r\n                                                                        </p>\r\n                                                                        <ul class="list-none pl-4 space-y-2">\r\n                                                                            <li\r\n                                                                                class="before:content-[''-''] before:mr-2">\r\n                                                                                Their parents are natives of Bihar.</li>\r\n                                                                            <li\r\n                                                                                class="before:content-[''-''] before:mr-2">\r\n                                                                                Their parents are domiciled in Bihar.\r\n                                                                            </li>\r\n                                                                            <li\r\n                                                                                class="before:content-[''-''] before:mr-2">\r\n                                                                                Their parents are registered refugees of\r\n                                                                                Bihar.</li>\r\n                                                                            <li\r\n                                                                                class="before:content-[''-''] before:mr-2">\r\n                                                                                Their parents are natives of other\r\n                                                                                states\r\n                                                                                but employees of Govt. of Bihar.</li>\r\n                                                                        </ul>\r\n\r\n                                                                        <p class="text-xl font-semibold mt-4">List of\r\n                                                                            courses offered at KEC:</p>', 50),
  ('academic.antiragging', 'main', 'academic', 'Anti Ragging: text', '<p><strong>Updated Soon&#8230</strong></p>', 10),
  ('academic.attendance', 'main', 'exam', 'Attendance: text', '<p><strong>Updated Soon &#8230</strong></p>', 10),
  ('academic.calender', 'main', 'exam', 'Academic Calender: links', '<ul class="list-disc pl-5 space-y-4">\r\n\r\n                        <li class="flex items-center hover:bg-blue-50 p-2 rounded transition duration-300 ease-in-out">\r\n                            <div class="flex-shrink-0">\r\n                                <i class="fa fa-calendar-alt text-blue-600 mr-2"></i>\r\n                            </div>\r\n                            <p>\r\n                                <span class="font-semibold">Bihar Engineering University Calendar:</span>\r\n                                <a href="http://beu-bih.ac.in/BEUP/Academic_Calendar.aspx" target="_blank" class="text-blue-600 hover:underline">Download</a>\r\n                            </p>\r\n                        </li>\r\n                    </ul>', 10),
  ('academic.mentors', 'main', 'academic', 'Mentors: text', '<p><strong>Updated Soon&#8230</strong></p>', 10),
  ('academic.notice', 'main', 'academic', 'Notice: text', '<p><strong>Updated Soon&#8230</strong></p>', 10),
  ('academic.paymenttutorial', 'main', 'fees', 'Fee payment tutorial: steps', '<h3 class="text-3xl font-bold mb-6 text-gray-800">Steps To Be Followed For Fee Payment:</h3>\r\n                        <div class="text-lg space-y-6 text-gray-700">\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 1:</strong> Open any browser.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 2:</strong> Go to the link <strong>onlinesbi.com/sbicollect</strong>. A page of "terms" will be opened.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 3:</strong> Tick the checkbox (acceptance of terms and conditions) and click on <strong>proceed</strong>. A new page will open.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 4:</strong> Select your <strong>State of Corporate/Institution</strong> (i.e., Bihar) and <strong>Type of Corporate/Institution</strong> (i.e., Educational Institutions), then click on <strong>Go</strong>. A new page will open.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 5:</strong> Select your <strong>Educational Institutions Name</strong> (i.e., Katihar Engineering College) and submit. A new page will open with the logo of Katihar Engineering College.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 6:</strong> Select <strong>Payment Category</strong> (i.e., either fees or fine depending upon what you are paying for).</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 7:</strong> Enter your details: Your Name, Registration no., Branch, Category, Email Id, Year/Semester, and fees (corresponding to the fee column).</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 8:</strong> Enter your Name, Date of Birth/Incorporation, Mobile no., Email Id, and the text shown in the image for banking, then <strong>Submit</strong>.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 9:</strong> A page with the details you entered will appear. Check the details carefully, and if correct, <strong>Submit</strong>.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 10:</strong> A page with several payment modes will open. Select the payment mode you prefer and complete the payment.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 11:</strong> After completing the payment, you can download the e-Receipt of payment.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Or you can also download the PDF containing screenshots of the steps for fee payment:</strong> <a href="/jsp/facilities/payment.pdf" target="_blank" class="text-blue-600 hover:underline">Click here to download</a></p>\r\n\r\n                </div>', 10),
  ('academic.regulations', 'main', 'academic', 'Academic Regulations: document', '<p>\r\n\r\n                    <div>\r\n                        <object data="/jsp/academic/regulation.pdf" type="application/pdf" width="700" height="1000">\r\n                            <embed src="/jsp/academic/regulation.pdf" type="application/pdf">\r\n                        </object>\r\n                    </div>\r\n                    </p>', 10),
  ('academic.rules', 'main', 'academic', 'Rules: text', '<p><strong>Updated Soon &#8230</strong></p>', 10),
  ('academic.syllabus', 'main', 'exam', 'Syllabus: links', '<p><code></p>\r\n                    <li>New Course Curriculum for Engineering & Technology for 1st & 2nd Semester based on AICTE Model Cirriculum to be followed from Session 2018-19 onwards <a href="http://akubihar.ac.in/Academics/Docs/NEW_CURRICULUM_ENGINEERING_TECHNOLOGY.pdf"\r\n                                                                                                                                                                                 rel="attachment wp-att-2593"> Download</a><br/></li>\r\n               <li>Revised B.tech Syllabus<a href="http://akubihar.ac.in/Academics/Docs/revised%20B%20tech%2019-02-11(revised).pdf">Download</a></li>', 10),
  ('academic.universityresults', 'main', 'exam', 'University Results: text', '<p class="text-center text-lg font-semibold text-gray-700">\r\n                   <strong>Updated Soon&#8230</strong>\r\n               </p>', 10),
  ('approval.akuapproval', 'main', 'approval', 'AKU Approval: document', '<object data="/jsp/approval/aku.pdf" type="application/pdf" width="700" height="1000">\r\n                    <embed src="/jsp/approval/aku.pdf" type="application/pdf">\r\n                </object>\r\n                <p><strong>AKU Regulation &#8212;-</strong></p>\r\n                <i class="fa fa-download"></i>\r\n                <a href="/jsp/approval/aku.pdf">\r\n                    <button type="button" class="btn btn-success" data-dismiss="modal">Download</button></a>', 10),
  ('approval.mandatorydisclosure', 'main', 'approval', 'Mandatory Disclosure: document', '<object data="/jsp/approval/aku.pdf" type="application/pdf" width="700" height="1000">\r\n          <embed src="/jsp/approval/aku.pdf" type="application/pdf">\r\n        </object>\r\n        <p><strong>AKU Regulation &#8212;-</strong></p>\r\n        <i class="fa fa-download"></i>\r\n        <a href="/jsp/approval/aku.pdf">\r\n          <button type="button" class="btn btn-success" data-dismiss="modal">Download</button></a>', 10),
  ('department.ash.about', 'intro', 'department.ash', 'About ASH: introduction', '<div id="ctl00_ContentPlaceHolder1_div_1">\r\n                       <p><strong class="text-3xl font-bold">INTRODUCTION</strong></p>\r\n                       <p>This department deals with all the basic concepts required to excel in the field of engineering. All the concepts of science, mathematics, humanities, and management are revisited, recalled, and interpreted to ease the understanding required to excel in the field.</p>\r\n                       <p>The department teaches subjects such as Chemistry, English, Mathematics, and Physics in the B.Tech programs. There are a number of well-qualified and experienced faculty members available to serve the department.</p>\r\n                       <p>The aspects such as technical communication, technical report writing, industrial economics, accountancy, industrial organization, their behavior, and psychology are taught under the section of humanities.</p>\r\n                       <p>The department of Applied Science consists of:</p>\r\n                       <ul class="list-disc pl-6">\r\n                           <li>Applied Physics</li>\r\n                           <li>Applied Chemistry</li>\r\n                           <li>Applied Mathematics</li>\r\n                       </ul>\r\n                       <p>This section deals with concepts such as semiconductor physics, optics, electrostatics, modern physics, solutions and their colligative properties, polymers, and practical aspects such as titration of chemicals, testing the pH value of solutions, and many more.</p>\r\n                       <p>Applied Mathematics offers courses to undergraduate and postgraduate students of various engineering disciplines. The syllabi have been designed in the areas of applied mathematics, computational techniques, and statistical testing to impart a sound knowledge of the various mathematical tools used and their applications in the engineering disciplines.</p>\r\n                   </div>', 10),
  ('department.ash.awards', 'main', 'department.ash', 'ASH Awards: text', '<p>Updated Soon&#8230;</p>', 10),
  ('department.ash.course', 'main', 'department.ash', 'ASH Course File: text', '<p>Updated Soon&#8230;</p>', 10),
  ('department.ash.labs', 'main', 'department.ash', 'ASH Labs: laboratory list', '<p><span\r\n                        style="color: #0000ff;"><strong>Departmental Laboratories</strong></span></p>\r\n                    <ol>\r\n\r\n                        <li>Applied Physics</li>\r\n                        <li>Applied Chemistry</li>\r\n                        <li>Environmental Science</li>\r\n\r\n                    </ol>', 10),
  ('department.ash.programs', 'main', 'department.ash', 'ASH Programs/Activities: text', '<p><strong>Updated Soon &#8230</strong></p>', 10),
  ('department.ash.students', 'main', 'department.ash', 'ASH Students: text', '<p><strong>Updated Soon &#8230</strong></p>', 10),
  ('department.ash.vision', 'main', 'department.ash', 'ASH Vision & Mission: text', '<p\r\n                                                    style="text-align: center;"><span\r\n                                                    style="text-decoration: underline; font-family: georgia, palatino; font-size: large; color: #800000;"><b>Vision of the Department</b></span>\r\n                                            </p>\r\n                                                <p style="padding-left: 30px; text-align: justify;"><span\r\n                                                        style="font-family: georgia, palatino; font-size: medium;">To achieve excellence in the education & to fulfill the vision of the department, the vision of the department is-<br>1.&bull;	To cater students to pursue both intellectual growth and professional development,          balance both depth and breadth in learning experience, practice both thoughtful reflection and active application.<br>2.To prepare our students for their successful career based on strong moral & ethical foundation in the first year itself.<br>3. To support different engineering streams to make them understand the basic concepts & thus to support the intellectual needs of the globe.<br>4.To create a healthy working culture in the department.</span>\r\n                                                </p>\r\n                                                <hr/>\r\n                                                <p style="text-align: center;"><span\r\n                                                        style="text-decoration: underline; font-family: georgia, palatino; font-size: large; color: #800000;"><b>Mission of the Department</b></span>\r\n                                                </p>\r\n                                                <ul>\r\n                                                    <li style="text-align: justify;"><span\r\n                                                            style="font-family: georgia, palatino; font-size: medium;">To enable students to develop their own abilities, talent & discover their teaming potential to the fullest recognized globally.</span>\r\n                                                    </li>\r\n                                                    <li style="text-align: justify;"><span\r\n                                                            style="font-family: georgia, palatino; font-size: medium;">To achieve above, Department of Applied Science and Humanities would provide strong foundation to the students through basic courses and expanded value added teaching in areas of technical field, personality development and competitive abilities.</span>\r\n                                                    </li>\r\n                                                    <li style="text-align: justify;"><span\r\n                                                            style="font-family: georgia, palatino; font-size: medium;">Encourage and motivate staff and students to utilize the facilities provided to them, with their innovative and creative thinking in an effective way for their overall development.</span>\r\n                                                    </li>\r\n\r\n                                                </ul>', 10),
  ('department.ash.weekly', 'main', 'department.ash', 'ASH Weekly Test Result: text', '<p><strong>Updated Soon &#8230</strong></p>', 10),
  ('department.cse.about', 'intro', 'department.cse', 'About CSE: introduction', '<div id="ctl00_ContentPlaceHolder1_div_1">\r\n                    <p><strong class="text-3xl font-bold">INTRODUCTION</strong></p>\r\n                    <p>Computer Science and Engineering is a sub-field of electronics engineering that covers only digital aspects of electronics engineering like computer architecture, processor designing, computer networks, etc. This department integrates the fields of computer engineering and computer science. CSE programs include core subjects of computer science such as:</p>\r\n                    <ul class="list-disc pl-6">\r\n                        <li>Operating systems</li>\r\n                        <li>Theory of computation</li>\r\n                        <li>Design and analysis of algorithms</li>\r\n                        <li>Data structures</li>\r\n                        <li>Database systems</li>\r\n                    </ul>\r\n                    <p>CSE branch is highly demanding and fastest growing subject. It will make human life better than ever before and that''s why a whole world has entered into new race named, "Development of computer technology". As a contribution to this race Katihar college of Engineering has established a department of computer science and engineering from the academic session 2016/17. The department offers Btech programme with the annual intake of 60 students and are working to increase the intake capabilities.</p>\r\n                    <p>The Department of Computer Science and Engineering of Katihar Engineering College, Katihar is ready to prepare well qualified, motivated, application oriented young and dynamic Computer Science graduates under the guidance of highly qualified faculties who inspire students, ignite students'' imagination and enrich them with their priceless knowledge and experience. The faculty of the Department are actively engaged in research in the areas of Data & Knowledge Management, Software Engineering, Image Processing, Cryptography, Data Mining, and Artificial Intelligence. Management keeps strong check on faculties and provoke them to attend workshops, seminars, conferences and faculty development program.</p>\r\n                </div>', 10),
  ('department.cse.attendance', 'main', 'department.cse', 'CSE Attendance: text', '<p>Updated Soon&#8230;</p>', 10),
  ('department.cse.awards', 'main', 'department.cse', 'CSE Awards: text', '<p>Updated Soon&#8230;</p>', 10),
  ('department.cse.course', 'main', 'department.cse', 'CSE Course File: text', '<p>Updated Soon&#8230;</p>', 10),
  ('department.cse.labs', 'main', 'department.cse', 'CSE Labs: laboratory list', '<p><span\r\n                        style="color: #0000ff;"><strong>Departmental Laboratories</strong></span></p>\r\n                    <ol>\r\n\r\n                        <li>Programming Problems</li>\r\n                        <li>Object Oriented Programming</li>\r\n                        <li>Data Structure</li>\r\n                        <li>Systems Programming</li>\r\n						<li>Introduction to Java Programming Language</li>\r\n						<li>DataBase Management Systems</li>\r\n						<li>Operating Systems</li>\r\n                    </ol>', 10),
  ('department.cse.programs', 'main', 'department.cse', 'CSE Programs/Activities: text', '<p><strong>Updated Soon &#8230</strong></p>', 10),
  ('department.cse.students', 'main', 'department.cse', 'CSE Students: text', '<p><strong>Updated Soon &#8230</strong></p>', 10),
  ('department.cse.vision', 'main', 'department.cse', 'CSE Vision & Mission: text', '<p\r\n                                                    style="text-align: center;"><span\r\n                                                    style="text-decoration: underline; font-family: georgia, palatino; font-size: large; color: #800000;"><b>Vision of the Department</b></span>\r\n                                            </p>\r\n                                                <p style="padding-left: 30px; text-align: justify;"><span\r\n                                                        style="font-family: georgia, palatino; font-size: medium;">To become a renowned institute in imparting high quality knowledge and in providing students a standard and smart learning and research experience in Computer Science and Engineering.</span>\r\n                                                </p>\r\n                                                <hr/>\r\n                                                <p style="text-align: center;"><span\r\n                                                        style="text-decoration: underline; font-family: georgia, palatino; font-size: large; color: #800000;"><b>Mission of the Department</b></span>\r\n                                                </p>\r\n                                                <ul>\r\n                                                    <li style="text-align: justify;"><span\r\n                                                            style="font-family: georgia, palatino; font-size: medium;">To prepare ourselves for organizing and attending different workshops and seminars in collaboration with bigger university such as IITs NITs and IIITs.</span>\r\n                                                    </li>\r\n                                                    <li style="text-align: justify;"><span\r\n                                                            style="font-family: georgia, palatino; font-size: medium;">Organise vocational training to develop socialist qualities among students.</span>\r\n                                                    </li>\r\n                                                    <li style="text-align: justify;"><span\r\n                                                            style="font-family: georgia, palatino; font-size: medium;">Encourage and motivate staff and students to utilize the facilities provided to them, with their innovative and creative thinking in an effective way for their overall development.</span>\r\n                                                    </li>\r\n\r\n                                                </ul>', 10),
  ('department.cse.weekly', 'main', 'department.cse', 'CSE Weekly Test Result: text', '<p><strong>Updated Soon &#8230</strong></p>', 10),
  ('facilities.bank', 'main', 'fees', 'Bank: payment instructions', '<p>\r\n                                                            <table border="1" width="500">\r\n                                                               <tr><td><p>For Detailed Instruction about payment </p></td>\r\n                                                               <td><i class="fa fa-download"></i>\r\n                                                                   <a href="/jsp/facilities/payment.pdf">\r\n                                                                   <button type="button" class="btn btn-success" data-dismiss="modal"style="margin-left" class="btn btn-success">click here\r\n                                                                   </button></a>\r\n                                                               </td>\r\n                                                               </tr>\r\n                                                            </table>                                    \r\n                                                                                                \r\n                                                        </p>', 10),
  ('facilities.centrallibrary', 'photo', 'library', 'Central Library: photo', '<img alt="Central Library" src="/jsp/facilities/central-library.jpeg"\r\n                                   class="img-responsive" style="margin: 25px 0;"/>', 10),
  ('facilities.centrallibrary', 'main', 'library', 'Central Library: text, links and contacts', '<div style="font-family: georgia, sans-serif; font-size: 16px; text-align: justify;">The library of the\r\n                    institute consists of plethora of books from various sectors of engineering. The well maintained\r\n                    library is embraced with various text books, reference books, magazines and daily newspapers. It is\r\n                    true that the heart of an engineering college lies in laboratory and library, keeping this goal in\r\n                    mind a full-fledged library is established with over thousands of books of the top publishers in the\r\n                    world.\r\n                    Each student is provided with three library cards which can be availed as per the requirement. The\r\n                    rich environment at the library provides an academic culture among the students and helps them to\r\n                    explore more about the subjects.<br>With over thousands books, the library also provides the\r\n                    facility of magazines and daily newpaper on the reading desk.\r\n                    <br/> <strong>Useful Links:</strong></p>\r\n                    <table style="width: 100%;">\r\n                        <tbody>\r\n                        <tr bgcolor="#e9feea">\r\n                            <th style="text-align: left;">National Digital Library of India</th>\r\n                            <th style="text-align: center;"><a href="http://ndl.iitkgp.ac.in/"><span\r\n                                    style="color: #0000ff;">Click Here</span></a></th>\r\n                            <th></th>\r\n                        </tr>\r\n                        <tr bgcolor="#e9feea">\r\n                            <td style="text-align: left;"><strong>NPTEL</strong></td>\r\n                            <td style="text-align: center;"><span style="color: #0000ff;"><strong><a\r\n                                    style="color: #0000ff;"\r\n                                    href="http://nptel.ac.in">Click Here </a></strong></span></td>\r\n                            <td></td>\r\n                        </tr>\r\n                        <tr bgcolor="#e9feea">\r\n                            <td><strong>SCIENCE DIRECT</strong></td>\r\n                            <td style="text-align: center;"><span style="color: #0000ff;"><strong><a\r\n                                    style="color: #0000ff;"\r\n                                    href="https://www.sciencedirect.com/">Click Here</a></strong></span></td>\r\n                            <td></td>\r\n                        </tr>\r\n                        <tr bgcolor="#e9feea">\r\n                            <td style="text-align: left;"><b>INTERNATIONAL CHILDREN&#8217;S DIGITAL LIBRARY</b></td>\r\n                            <td style="text-align: center;"><span style="color: #0000ff;"><strong><a\r\n                                    style="color: #0000ff;"\r\n                                    href="http://en.childrenslibrary.org/">Click Here </a></strong></span></td>\r\n                            <td></td>\r\n                        </tr>\r\n                        <tr bgcolor="#e9feea">\r\n                            <td style="text-align: left;"><b>SWAYAM</b></td>\r\n                            <td style="text-align: center;"><span style="color: #0000ff;"><strong><a\r\n                                    style="color: #0000ff;"\r\n                                    href="https://swayam.gov.in/">Click Here </a></strong></span></td>\r\n                            <td></td>\r\n                        </tr>\r\n                        </tbody>\r\n                    </table>\r\n                    <p><strong>Library Contact Person :-</strong></p></div>\r\n                <table id="ctl00_ContentPlaceHolder1_GridView2" style="height: 116px;" border="0" width="834"\r\n                       cellspacing="2" cellpadding="4">\r\n                    <tbody>\r\n                    <tr align="center">\r\n                        <th style="text-align: left;" scope="col"><a>Name</a></th>\r\n                        <th style="text-align: right;" scope="col"><a> Designation</a></th>\r\n                    </tr>\r\n                    <tr bgcolor="#e9feea">\r\n                        <td>Mr. Alauddin Ansari, Assistant Prof(EEE)</td>\r\n                        <td style="text-align: right;">Professor-in-Charge</td>\r\n                    </tr>\r\n                    <tr bgcolor="#e9feea">\r\n                        <td>Mrs Shweta Kumari, Assistant Prof (CSE)</td>\r\n                        <td style="text-align: right;">Professor-in-Charge</td>\r\n                    </tr>\r\n\r\n                    </tbody>\r\n                </table>', 20),
  ('facilities.club', 'main', 'activities', 'Clubs: text and contacts', '<span\r\n                            style="font-family: Georgia, Palatino;"><strong>Cultural Club</strong></span></p>\r\n                <div style="font-family: Arial, Helvetica, sans-serif; font-size: 16px; text-align: justify;"> The\r\n                    institution has always shown keen interest in promoting all the cultural activities for not only\r\n                    developing the cultural minds but also to encourage the hidden talent among the students. The\r\n                    cultural fest is organised every year for stimulating these venture. The students of the college has\r\n                    also shown their talents in various platforms and has always supported with their enthusiasm to\r\n                    conduct campaigns like these.The institution provides an excellent platform to give shape to the\r\n                    innovative ideas and thoughts under the able stewardship of faculty members.</p></div>\r\n                <div>\r\n                    <table style="width: 100%;" border="1" align="center" bgcolor="#7eec35">\r\n                        <tbody>\r\n                        <tr bgcolor="#7eec35">\r\n                            <th style="text-align: left;" scope="col"><a>Designation</a></th>\r\n                            <th style="text-align: left;" scope="col"><a>Name</a></th>\r\n                            <th style="text-align: left;" scope="col"><a>Contact No</a></th>\r\n                        </tr>\r\n                        <tr bgcolor="#e9feea">\r\n                            <td>Prof. In-charge</td>\r\n                            <td>Md Talib Ahmad</td>\r\n                            <td>9108006551</td>\r\n                        </tr>\r\n                        <tr bgcolor="#e9feea">\r\n                            <td>Prof. In-charge</td>\r\n                            <td>Dharmveer Kumar Yadav</td>\r\n                            <td>8757760847</td>\r\n                        </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>', 10),
  ('facilities.csecenter', 'photo', 'facilities', 'Computer Centre: photo', '<img alt="Central Library" src="../wp-content/uploads/2018/img3.JPG"\r\n                                                                 class="img-responsive" style="margin: 25px 0; width: 800px"/>', 10),
  ('facilities.csecenter', 'main', 'facilities', 'Computer Centre: text', '<div style="font-family: Arial, Helvetica, sans-serif; font-size: 16px; text-align: justify;"><span\r\n                        style="font-family: Georgia, Palatino;">Katihar Engineering College is augmented with a total of approax 50 computers in computer centre with centralised power supply. All the machines is enrich with top-notch quality of processors and other hardwares. All the system consists of different softwares from all the fields of Engineering to provide the best facilities to the students and the Professors. The computer centre also consists a smart platform for studies. There is a projector for smart way of learning things. A number of lab such as MATLAB, High level Programming lab, Assembly Language Programming Lab, Implementation on Linux OS, CAD, CAM, DBMS, Language Lab and competetive programming is provided to the students for their overall development.  </span><br/>\r\n                    <span style="font-family: Georgia, Palatino;">All academic buildings, library, administrative blocks, residential buildings, and all the hostels of KEC are provided the Wi-Fi facility with a number of access points. All the members of college is allowed to access the computer systems. All the resources in the centre is utilised very efficiently in order to provide the plethora of knowledge in the respective fields. A number of presentations, exams, classes, lab classes are arranged on regular basis using the resources to provide the best education to the students.</span></p>\r\n\r\n                </div>', 20),
  ('facilities.guesthouse', 'main', 'facilities', 'Guest House: text', '<p>Updated Soon&#8230;</p>', 10),
  ('facilities.gymnasium', 'main', 'activities', 'Gymnasium: text', '<p>\r\n\r\n               Currently Katihar Engineering College doesn''t provide any Gymnasium Facility.\r\n\r\n            </p>', 10),
  ('facilities.healthcenter', 'main', 'facilities', 'Health Centre: text', '<p>Updated Soon&#8230;</p>', 10),
  ('facilities.hostels', 'intro', 'hostel', 'Hostels: introduction', '<h1\r\n                        id="ctl00_ContentPlaceHolder1_h4_heading">Hostels</h1>\r\n\r\n\r\n\r\n                    <p> Currently Katihar Engineering college provides three hostels named : Krishna Girls Hostel , Neelgiri and Shivalik\r\n                    </p>\r\n                    <p><strong>The administration of hostels is under the supervision of following\r\n                        professors in charge:-</strong></p>\r\n                    <br>     <br>', 10),
  ('facilities.hostels', 'incharges', 'hostel', 'Hostels: in-charges table', '<table class="table">\r\n                                    <thead>\r\n                                    <tr>\r\n                                        <th scope="col">#</th>\r\n                                        <th scope="col">Hostel Name</th>\r\n                                        <th scope="col">Superintendent</th>\r\n                                        <th scope="col">Assistant Superintendent</th>\r\n                                    </tr>\r\n                                    </thead>\r\n                                    <tbody>\r\n                                    <tr>\r\n                                        <th scope="row">1</th>\r\n                                        <td>Krishna Girls Hostel </td>\r\n                                        <td>Ms. Sneha Kumari</td>\r\n                                        <td>Ms. Kumari Shipra Suman</td>\r\n                                    </tr>\r\n                                    <tr>\r\n                                        <th scope="row">2</th>\r\n                                        <td>Neelgiri</td>\r\n                                        <td>Mr. Rajeev Ranjan Sinha</td>\r\n                                        <td>Mr.Mukesh Kumar</td>\r\n                                    </tr>\r\n                                    <tr>\r\n                                        <th scope="row">3</th>\r\n                                        <td>Shivalik</td>\r\n                                        <td>Dr. Arbind Prasad</td>\r\n                                        <td>Mr.Ramchandra Kumar</td>\r\n                                    </tr>\r\n                                    </tbody>\r\n                                </table>', 20),
  ('facilities.hostels', 'fees', 'hostel', 'Hostels: fee structure table', '<table class="table">\r\n                                    <thead>\r\n                                    <tr>\r\n                                        <th scope="col">#</th>\r\n                                        <th scope="col">Hostel Charge Name</th>\r\n                                        <th scope="col">Amount (in INR)</th>\r\n                                    </tr>\r\n                                    </thead>\r\n                                    <tbody>\r\n                                    <tr>\r\n                                        <th scope="row">1</th>\r\n                                        <td>Hostel Admission Charge</td>\r\n                                        <td>1000/-</td>\r\n\r\n                                    </tr>\r\n                                    <tr>\r\n                                        <th scope="row">2</th>\r\n                                        <td>Hostel Maintainance Charge</td>\r\n                                        <td>6000/- (for Six Months 6 * 1000=6000)</td>\r\n                                    </tr>\r\n                                    <tr>\r\n                                        <th scope="row">3</th>\r\n                                        <td>Mess Charge/Fooding Charge:- </td>\r\n                                        <td>3000/- per Month</td>\r\n                                    </tr>\r\n                                    </tbody>\r\n                                </table>', 30),
  ('facilities.hostels', 'instructions', 'hostel', 'Hostels: instructions', '<ul>\r\n                                    <li><p>Mess charge will be taken for 3 months at the time of admisssion 3 * 3000 = 9000/- </p></li>\r\n                                    <li><p>Total Hostel charge (Maintainance + Mess) to be deposited at the time of Admission  <br>\r\n                                        <ul>\r\n                                            <li> 7000/-</li>\r\n                                            <li>9000/-</li>\r\n                                            <li>16000/-</li>\r\n                                        </ul>\r\n\r\n\r\n                                    </li>\r\n                                </ul>', 40),
  ('facilities.medicalfacilities', 'main', 'facilities', 'Medical Facilities: text', '<p>\r\n                Updated Soon&#8230;</p>', 10),
  ('facilities.placementbrochure', 'main', 'tp', 'Placement Brochure: document', '<p>\r\n\r\n\r\n                    <div>\r\n                        <object data="/jsp/trainingplacement/brochure.pdf" type="application/pdf" width="700" height="1000">\r\n                            <embed src="/jsp/trainingplacement/brochure.pdf" type="application/pdf">\r\n                        </object>\r\n                    </div>\r\n                    </p>', 10),
  ('facilities.sportsfacilities', 'main', 'activities', 'Sports Facilities: text and contacts', '<div style="font-family: georgia, sans-serif; font-size: 16px; text-align: justify;"><p\r\n                        id="ctl00_ContentPlaceHolder1_h4_heading"><span\r\n                        style="font-family: Georgia, Palatino;"><strong>Sports Club</strong></span></p>\r\n                    <div id="ctl00_ContentPlaceHolder1_div_3">The Institution has a rich culture of both outdoor and\r\n                        indoor games. An annual sports festival is organised every year for the physical development of\r\n                        the students.\r\n                        The college has well-of equipments for different sports. College is very much inclined to\r\n                        promote the modern day sports. It also has a special club for the development, promotion and\r\n                        organisation of sports. At regular intervals different sports events for sports like cricket,\r\n                        football, volleyball, badminton, carrom, chess is orgainsed. The different equipments for the\r\n                        games are available in college store and they can be issued from the permission of the\r\n                        Prof-in-charge of Sports and Cultural department. They take care of all the sports activities,\r\n                        supervise the development of games and guide the students to be fit mentally, physically and\r\n                        spiritually.<span style="font-family: Georgia, Palatino;"></span><br/>\r\n                        <span style="font-family: Georgia, Palatino;"></span>\r\n                    </div>\r\n                    <div>\r\n                        <table style="width: 100%;" border="1" align="center" bgcolor="#7eec35">\r\n                            <tbody>\r\n                            <tr bgcolor="#7eec35">\r\n                                <th style="text-align: left;" scope="col"><a>Designation</a></th>\r\n                                <th style="text-align: left;" scope="col"><a>Name</a></th>\r\n                                <th style="text-align: left;" scope="col"><a>Contact No</a></th>\r\n                            </tr>\r\n                            <tr bgcolor="#e9feea">\r\n                                <td>Prof. In-charge</td>\r\n                                <td>Md Talib Ahmad</td>\r\n                                <td></td>\r\n                            </tr>\r\n                            <tr bgcolor="#e9feea">\r\n                                <td>Prof. In-charge</td>\r\n                                <td>Dharmveer Kumar </td>\r\n                                <td></td>\r\n                            </tr>\r\n                            </tbody>\r\n                        </table>\r\n                    </div>\r\n                </div>', 10),
  ('facilities.startupcell', 'main', 'tp', 'Startup Cell: text', '<strong>Updated Soon &#8230</strong>', 10),
  ('facilities.usefulllink', 'main', 'facilities', 'Useful Links: text', '<p>Updated Soon&#8230;</p>', 10),
  ('facilities.wifi', 'main', 'facilities', 'Wi-Fi: text', '<div style="font-family: georgia, sans-serif; font-size: 16px; text-align: justify;">\r\n                    Internet\r\n                    nowadays has become even more necessary than the basic necessities (e.g., water, air and food) in\r\n                    our life. It explores huge knowledge, information and entertainment. Presently, everywhere class\r\n                    tests, study courses, data records become more familiar with online, students no longer have to look\r\n                    for offline studies to prepare for their futures. To help the academic campus friendly, KEC Katihar\r\n                    is well connected for ISP (Internet Service Provider) via broadband network upto data rate nearly\r\n                    4Mbps provided by BSNL Katihar. The LAN services are available during working hours (9:00 AM to\r\n                    5&nbsp;PM) daily. Currently, Wi-Fi services are restricted to certain areas like academic buildings and\r\n                    certain departments.\r\n\r\n                    <br>The current data rate 4Mbps is low in the current campus\r\n                    based on our Internet requirements. But, our institute has planned for high speed data rated\r\n                    LAN as well as Wi-Fi everywhere within the campus in our new campus which is currently under the\r\n                    construction.</div>', 10),
  ('home', 'marquee', 'home', 'Home: scrolling links before the notices', '<div class="flex  items-center">\r\n          <img class="w-8 h-auto" src="/sites/noticeicon.gif" alt="Notice Icon">\r\n          <a href="https://youtu.be/cYMNEnq52p8" target="_blank" class="text-blue-700 hover:underline">\r\n            VIDEO FOR EVC AICTE\r\n          </a>\r\n        </div>\r\n\r\n        <div class="flex  items-center">\r\n          <img class="w-8 h-auto" src="/sites/noticeicon.gif" alt="Notice Icon">\r\n          <a href="https://tpo.keckatihar.in" target="_blank" class="text-blue-700 hover:underline">\r\n            Placement Portal of Katihar Engineering College\r\n          </a>\r\n        </div>\r\n\r\n\r\n\r\n        <div class="flex items-center">\r\n          <img class="w-8 h-auto" src="/sites/noticeicon.gif" alt="Notice Icon">\r\n          <a href="https://www.aicte-india.org/feedback/" target="_blank" class="text-blue-700 hover:underline">\r\n            Click here to give feedback to A.I.C.T.E\r\n          </a>\r\n        </div>', 10),
  ('home', 'importantlinks', 'home', 'Home: Important Links', '<div class="link">\r\n        &raquo; <a href="http://socialwelfare.bih.nic.in/" target="_blank">Social Welfare Dept. Bhar</a>\r\n      </div>\r\n      <div class="link">\r\n        &raquo; <a href="http://dstbihar.gov.in/" target="_blank">DST Bihar</a>\r\n      </div>\r\n      <div class="link">\r\n        &raquo; <a href="http://www.educationbihar.gov.in/login.aspx?ReturnUrl=%2fDefault.aspx">Education Dept.\r\n          Bihar</a>\r\n      </div>\r\n      <div class="link">\r\n        &raquo; <a href="http://gov.bih.nic.in/" target="_blank">Govt. of Bihar</a>\r\n      </div>\r\n      <div class="link">\r\n        &raquo; <a href="http://bceceboard.bihar.gov.in/" target="_blank">BCECEB</a>\r\n      </div>\r\n      <div class="link">\r\n        &raquo; <a href="http://akubihar.ac.in/" target="_blank">AKU, Patna</a>\r\n      </div>\r\n      <div class="link">\r\n        &raquo; <a href="https://www.aicte-india.org/" target="_blank">AICTE</a>\r\n      </div>\r\n      <div class="link">\r\n        &raquo; <a href="https://jeemain.nic.in/webinfo/Public/Home.aspx" target="_blank">Joint Entrance Examination</a>\r\n      </div>', 20),
  ('home', 'about', 'home', 'Home: About KEC', '<p class="p-3" style=""><strong>Katihar\r\n                      Engineering College (KEC), Katihar </strong>with the advent of technology and the\r\n                    emergence of notable education in our society, had decided to adapt the prevailing need\r\n                    of light. In the mission to achieve the eminence in the field, the establishment of\r\n                    Katihar Engineering College was laid in the year 2016. The college is enriched with a\r\n                    pollyannaish environment, highly motivated and enthusiastic students guided by well\r\n                    qualified professional from different prestigious colleges of our country. The college\r\n                    was established with three branches- Civil Engineering, Mechanical Engineering and\r\n                    Computer Science and Engineering. Each branch has a number of renowned professors with\r\n                    high qualifications and experience in teaching or their respective industries. The\r\n                    college consists of a central library, Computer Labs, Training and Placement Cell,\r\n                    Programmer''s Club etc, with the exceptional support staffs and infrastructure. All the\r\n                    labs and other infrastructure is in highly conditional states serving at their best to\r\n                    provide the best facilities to all the members of the college. Student of the college\r\n                    have exhibited their skill at different platform and gathered many awards from premium\r\n                    institutes. It is situated 3 km from Katihar Railway Station and there is a good\r\n                    transportation facility available from there. The college new campus in Hajipur, Katihar near NH 31\r\n                    has been completed and is now fully operational.<a href="/about/history">more</a>...</p>', 30),
  ('home', 'gallery', 'home', 'Home: Gallery pictures', '<ul class="flex flex-col md:flex-row md:space-x-8 space-y-4 md:space-y-0">\r\n                <li\r\n                  class="views-row views-row-1 views-row-odd views-row-first flex-1 animate-slide-in delay-0 group-hover:animate-slide-in-hover">\r\n                  <div class="views-field views-field-field-image">\r\n                    <div class="field-content">\r\n                      <a href="/images/sportkec.jpeg" target="_blank">\r\n                        <img typeof="foaf:Image"\r\n                          class="w-full h-auto object-cover rounded-lg transition-transform transform hover:scale-105 hover:shadow-2xl"\r\n                          src="/images/sportkec.jpeg" alt="Pitch for a Better India" />\r\n                      </a>\r\n                    </div>\r\n                  </div>\r\n                </li>\r\n                <li\r\n                  class="views-row views-row-2 views-row-even flex-1 animate-slide-in delay-300 group-hover:animate-slide-in-hover">\r\n                  <div class="views-field views-field-field-image">\r\n                    <div class="field-content">\r\n                      <a href="/images/sportkec1.jpeg">\r\n                        <img typeof="foaf:Image"\r\n                          class="w-full h-auto object-cover rounded-lg transition-transform transform hover:scale-105 hover:shadow-2xl"\r\n                          src="/images/sportkec1.jpeg" alt="Ace the Psychometric" />\r\n                      </a>\r\n                    </div>\r\n                  </div>\r\n                </li>\r\n                <li\r\n                  class="views-row views-row-3 views-row-odd views-row-last flex-1 animate-slide-in delay-600 group-hover:animate-slide-in-hover">\r\n                  <div class="views-field views-field-field-image">\r\n                    <div class="field-content">\r\n                      <a href="/images/sportkec.jpeg">\r\n                        <img typeof="foaf:Image"\r\n                          class="w-full h-auto object-cover rounded-lg transition-transform transform hover:scale-105 hover:shadow-2xl"\r\n                          src="/images/sportkec.jpeg" alt="Machine Assembly and Disassembly Workshop" />\r\n                      </a>\r\n                    </div>\r\n                  </div>\r\n                </li>\r\n              </ul>', 40),
  ('home', 'video', 'home', 'Home: Video Gallery video', '<ul class="space-y-6">\r\n              <li>\r\n                <div class="p-5">\r\n                  <div class="relative pb-9/16">\r\n                    <iframe frameborder="0" height="200" src="https://www.youtube.com/embed/1zoSI1yATFI" width="100%"\r\n                      class="w-full"></iframe>\r\n\r\n                  </div>\r\n                </div>\r\n              </li>\r\n            </ul>', 50),
  ('home', 'map', 'home', 'Home: map', '<iframe class="w-full h-full rounded-lg" title="Map"\r\n            src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3599.068905329472!2d87.53685667484957!3d25.56937421652652!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x39faaa69a3dfa627%3A0x1199a7446d2476a5!2sKatihar%20Engineering%20College%2C%20Katihar!5e0!3m2!1sen!2sin!4v1721727985690!5m2!1sen!2sin"\r\n            frameBorder="0" allowFullScreen="" aria-hidden="false" tabIndex="0"></iframe>', 60),
  ('legal.feestructure', 'main', 'fees', 'Fee Structure: heading and fee table', '<h3 class="text-center text-xl font-semibold mt-2"><u>Fee Structure for Day Scholars</u></h3>\r\n\r\n        <div class="overflow-x-auto mt-6">\r\n            <table class="min-w-full border border-gray-300">\r\n                <thead class="bg-gray-200">\r\n                    <tr>\r\n                        <td rowspan="2" class="border border-gray-300 p-2 text-left"><b>SI. No.</b></td>\r\n                        <td colspan="4" class="border border-gray-300 p-2 text-center"><b>General / BC / EBC</b></td>\r\n                        <td colspan="4" class="border border-gray-300 p-2 text-center"><b>SC / ST</b></td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class="border border-gray-300 p-2 text-center">1st year</td>\r\n                        <td class="border border-gray-300 p-2 text-center">2nd year</td>\r\n                        <td class="border border-gray-300 p-2 text-center">3rd year</td>\r\n                        <td class="border border-gray-300 p-2 text-center">4th year</td>\r\n                        <td class="border border-gray-300 p-2 text-center">1st year</td>\r\n                        <td class="border border-gray-300 p-2 text-center">2nd year</td>\r\n                        <td class="border border-gray-300 p-2 text-center">3rd year</td>\r\n                        <td class="border border-gray-300 p-2 text-center">4th year</td>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                    <tr>\r\n                        <td class="border border-gray-300 p-2 text-left">(i) Registration fee</td>\r\n                        <td class="border border-gray-300 p-2 text-center">2500.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">2500.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">2500.00</td>\r\n            