">00.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">00.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">00.00</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class="border border-gray-300 p-2 text-left">(iv) Admission fee</td>\r\n                        <td class="border border-gray-300 p-2 text-center">10.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">10.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">10.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">10.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">10.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">10.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">10.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">10.00</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class="border border-gray-300 p-2 text-left">(v) Examination fee</td>\r\n                        <td class="border border-gray-300 p-2 text-center">7400.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">7400.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">7400.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">7900.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">1400.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">1400.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">1400.00</td>\r\n                        <td class="border border-gray-300 p-2 text-center">1900.00</td>\r\n                    </tr>\r\n                    <t