  ('legal.privacypolicy', 'main', 'legal', 'Privacy Policy: text', '<ul class="list-disc list-inside space-y-4">\r\n                <li>\r\n                    All decisions undertaken by the Management & Governing body are termed to be final.\r\n                </li>\r\n                <li>\r\n                    All disputes are to be settled arbitrarily under the chairmanship of the Principal, Katihar Engineering College, Katihar.\r\n                </li>\r\n                <li>\r\n                   No documents are to be disclosed or published in public without written directive from the Principal, Katihar Engineering College, Katihar.\r\n                </li>\r\n            </ul>', 10),
  ('legal.productandservices', 'main', 'legal', 'Product and Services: courses table', '<h3 class="text-xl font-semibold mb-4">Course Offered</h3>\r\n            <div class="overflow-x-auto">\r\n                <table class="min-w-full border border-gray-300">\r\n                    <thead class="bg-gray-200">\r\n                        <tr>\r\n                            <th class="py-2 px-4 text-left font-semibold border-b border-gray-300">Course Name</th>\r\n                            <th class="py-2 px-4 text-left font-semibold border-b border-gray-300">Course Duration</th>\r\n                            <th class="py-2 px-4 text-left font-semibold border-b border-gray-300">Course Level</th>\r\n                        </tr>\r\n                    </thead>\r\n                    <tbody>\r\n                        <tr>\r\n                            <td class="py-2 px-4 border-b border-gray-300">Computer Science and Engineering</td>\r\n                            <td class="py-2 px-4 border-b border-gray-300">4 years</td>\r\n                            <td class="py-2 px-4 border-b border-gray-300">Graduation</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td class="py-2 px-4 border-b border-gray-300">Civil Engineering</td>\r\n                            <td class="py-2 px-4 border-b border-gray-300">4 years</td>\r\n                            <td class="py-2 px-4 border-b border-gray-300">Graduation</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td class="py-2 px-4 border-b border-gray-300">Electrical and Electronics Engineering</td>\r\n                            <td class="py-2 px-4 border-b border-gray-300">4 years</td>\r\n                            <td class="py-2 px-4 border-b border-gray-300">Graduation</td>\r\n                        </tr>\r\n                         <tr>\r\n                                                    <td class="py-2 px-4 border-b border-gray-300"> Electronics Engineering(VLSI Design and Technology)</td>\r\n                                                    <td class="py-2 px-4 border-b border-gray-300">4 years</td>\r\n                                                    <td class="py-2 px-4 border-b border-gray-300">Graduation</td>\r\n                                                </tr>\r\n                        <tr>\r\n                        <tr>\r\n                            <td class="py-2 px-4 border-b border-gray-300">Mechanical Engineering</td>\r\n                            <td class="py-2 px-4 border-b border-gray-300">4 years</td>\r\n                            <td class="py-2 px-4 border-b border-gray-300">Graduation</td>\r\n                        </tr>\r\n                         <tr>\r\n                                                    <td class="py-2 px-4 border-b border-gray-300">Mechanical and Smart Manufacturing Engineering</td>\r\n                                                    <td class="py-2 px-4 border-b border-gray-300">4 years</td>\r\n                                                    <td class="py-2 px-4 border-b border-gray-300">Graduation</td>\r\n                                                </tr>\r\n                            <td class="py-2 px-4">Food Processing</td>\r\n                            <td class="py-2 px-4">4 years</td>\r\n                            <td class="py-2 px-4">Graduation</td>\r\n                        </tr>\r\n                    </tbody>\r\n                </table>\r\n            </div>', 10),
